/**
 * Retell webhook handler
 * Processes call completion callbacks
 */

import type { Env, RetellWebhookPayload } from '../lib/types';
import { determineOutcome, isFinalOutcome, isRetryOutcome } from '../lib/outcomes';
import { calculateRetry } from '../lib/retry';
import {
  releaseLead,
  updateCallAttemptFromWebhook,
  updateCallAnalytics,
  markLeadCompleted,
  updateLeadForRetry,
  getLeadById,
  getCentreById,
  setSkyvernTaskId,
  updateBookingStatus,
} from '../services/supabase';
import { triggerBooking, validateTourDate } from '../services/skyvern';

/**
 * Handles Retell webhook callbacks
 * POST /webhook/retell
 */
export async function handleRetellWebhook(request: Request, env: Env): Promise<Response> {
  let payload: RetellWebhookPayload;

  try {
    payload = await request.json();
  } catch {
    return errorResponse(400, 'Invalid JSON body');
  }

  // Retell sends { event: "call_ended", call: {...} } - extract the call object
  const callData = payload.call || payload;

  // Extract data from payload
  const callId = callData.call_id;
  const metadata = callData.metadata || {};
  const callAnalysis = callData.call_analysis || {};

  const leadId = metadata.lead_id;
  const centreId = metadata.centre_id;
  const attemptNumber = parseInt(String(metadata.attempt_number)) || 1;
  const campaignType = metadata.campaign_type || 'reactivation';

  // Validate required fields
  if (!leadId) {
    console.warn('Webhook received without lead_id:', callId);
    return errorResponse(400, 'Missing lead_id in metadata');
  }

  // Determine outcome - check custom_analysis_data first (where Retell puts custom fields)
  const customData = callAnalysis.custom_analysis_data || {};
  const outcome = determineOutcome(
    customData.outcome || callAnalysis.outcome || callAnalysis.call_outcome,
    callData.disconnection_reason
  );

  const durationMs = callData.duration_ms || callData.call_length_ms || 0;
  const durationSeconds = Math.round(durationMs / 1000);
  // Custom analysis fields are in custom_analysis_data
  const emailPermission = customData.email_permission || callAnalysis.email_permission || false;
  const appointmentBooked = customData.appointment_booked || callAnalysis.appointment_booked || false;
  const callSummary = customData.detailed_call_summary || callAnalysis.detailed_call_summary || callAnalysis.call_summary || '';

  console.log(`Processing webhook for lead ${leadId}: outcome=${outcome}, duration=${durationSeconds}s`);

  try {
    // 1. Release the lead (decrement active_calls counter)
    await releaseLead(env, leadId);

    // 2. Update call_attempts record
    if (callId) {
      await updateCallAttemptFromWebhook(env, callId, {
        outcome,
        call_summary: callSummary,
        email_permission: emailPermission,
        appointment_booked: appointmentBooked,
        duration_seconds: durationSeconds,
        webhook_payload: payload,
      });
    }

    // 3. Update analytics
    if (centreId) {
      await updateCallAnalytics(env, centreId, campaignType, outcome, durationSeconds);
    }

    // 4. Route by outcome
    if (isFinalOutcome(outcome)) {
      // Mark lead as completed
      await markLeadCompleted(env, leadId, {
        last_outcome: outcome,
        appointment_booked: appointmentBooked,
        email_permission: emailPermission,
        detailed_call_summary: callSummary,
      });

      // Trigger Skyvern if booked (wrapped in try/catch - booking columns may not exist yet)
      if (outcome === 'booked' && appointmentBooked && centreId) {
        try {
          const customData = callAnalysis.custom_analysis_data || {};
          const tourDate = customData['Tour Date'] || customData.tour_date || '';
          const tourTime = customData['Tour Time'] || customData.tour_time || '';
          const childName = customData['Child First Name'] || customData.child_name || '';
          const childAge = customData["Child's Age"] || customData.child_age || '';

          let childBirthYear: number | undefined;
          if (childAge && !isNaN(parseInt(childAge))) {
            childBirthYear = new Date().getFullYear() - parseInt(childAge);
          }

          const [leadData, centreData] = await Promise.all([
            getLeadById(env, leadId),
            getCentreById(env, centreId),
          ]);

          if (leadData && centreData?.availability_api_url) {
            const selectedSlot = callAnalysis.selected_slot || extractSlotFromSummary(callSummary);

            const bookingResult = await triggerBooking(env, {
              action: 'book_tour',
              lead_id: leadId,
              centre_id: centreId,
              first_name: leadData.first_name,
              last_name: leadData.last_name,
              phone: leadData.phone,
              email: leadData.email || '',
              calendar_url: centreData.availability_api_url,
              selected_slot: selectedSlot,
              call_summary: callSummary,
              tour_date: tourDate,
              tour_time: tourTime,
              child_name: childName || leadData.first_name,
              child_birth_year: childBirthYear,
            });

            if (bookingResult.success && bookingResult.task_id) {
              await setSkyvernTaskId(env, leadId, bookingResult.task_id, tourDate, tourTime);
              console.log(`Skyvern task ${bookingResult.task_id} tracked for lead ${leadId}`);
            } else if (!bookingResult.success) {
              await updateBookingStatus(env, leadId, {
                booking_status: 'failed',
                booking_failure_reason: bookingResult.error || 'Unknown error',
              });
              console.warn(`Skyvern booking failed for lead ${leadId}: ${bookingResult.error}`);
            }
          } else {
            console.warn('Missing lead or centre data for Skyvern booking:', { leadId, centreId });
            await updateBookingStatus(env, leadId, {
              booking_status: 'failed',
              booking_failure_reason: 'Missing lead or centre data',
            });
          }
        } catch (bookingError) {
          console.error(`Skyvern booking error for lead ${leadId} (booking columns may need migration):`, bookingError);
        }
      }
    } else if (isRetryOutcome(outcome)) {
      // Calculate retry timing
      const retry = calculateRetry(attemptNumber - 1, [], null); // Windows tracked in DB

      await updateLeadForRetry(env, leadId, {
        status: retry.newStatus,
        attempt_count: retry.newAttemptCount,
        call_windows_tried: retry.callWindowsTried,
        next_call_after: retry.nextCallAfter,
        last_outcome: outcome,
        detailed_call_summary: callSummary,
      });
    } else {
      // Unknown outcome - mark as pending for manual review
      await updateLeadForRetry(env, leadId, {
        status: 'pending',
        attempt_count: attemptNumber,
        call_windows_tried: [],
        next_call_after: null,
        last_outcome: outcome,
        detailed_call_summary: callSummary,
      });
    }

    return new Response(
      JSON.stringify({
        status: 'ok',
        lead_id: leadId,
        outcome,
      }),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Webhook processing error:', error);
    return errorResponse(500, `Processing failed: ${error}`);
  }
}

function errorResponse(status: number, message: string): Response {
  return new Response(
    JSON.stringify({
      status: 'error',
      error: message,
    }),
    {
      status,
      headers: { 'Content-Type': 'application/json' },
    }
  );
}

/**
 * Extracts a selected time slot from the call summary
 * Looks for patterns like "Thursday February 5 at 6pm" or "2026-02-05 at 6:00 PM"
 */
function extractSlotFromSummary(summary: string): string {
  if (!summary) return '';

  // Look for day + date + time pattern (e.g., "Thursday February 5 at 6pm")
  const dayPattern = /(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\s+\w+\s+\d{1,2}\s+at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)/i;
  const dayMatch = summary.match(dayPattern);
  if (dayMatch) return dayMatch[0];

  // Look for ISO date + time pattern (e.g., "2026-02-05 at 6:00 PM")
  const isoPattern = /\d{4}-\d{2}-\d{2}\s+at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)/i;
  const isoMatch = summary.match(isoPattern);
  if (isoMatch) return isoMatch[0];

  // Look for just time if date context is elsewhere
  const timePattern = /\d{1,2}(?::\d{2})?\s*(?:am|pm)/i;
  const timeMatch = summary.match(timePattern);
  if (timeMatch) return timeMatch[0];

  return '';
}

