// 4. Route by outcome
if (isFinalOutcome(outcome)) {
  // Mark lead as completed
  await markLeadCompleted(env, leadId, {
    last_outcome: outcome,
    appointment_booked: appointmentBooked,
    email_permission: emailPermission,
    detailed_call_summary: callSummary,
  });

  // Trigger Skyvern if booked (wrapped in try/catch - booking columns may not exist yet)
  if (outcome === 'booked' && appointmentBooked && centreId) {
    try {
      const customData = callAnalysis.custom_analysis_data || {};
      const tourDate = customData['Tour Date'] || customData.tour_date || '';
      const tourTime = customData['Tour Time'] || customData.tour_time || '';
      const childName = customData['Child First Name'] || customData.child_name || '';
      const childAge = customData["Child's Age"] || customData.child_age || '';

      let childBirthYear: number | undefined;
      if (childAge && !isNaN(parseInt(childAge))) {
        childBirthYear = new Date().getFullYear() - parseInt(childAge);
      }

      const [leadData, centreData] = await Promise.all([
        getLeadById(env, leadId),
        getCentreById(env, centreId),
      ]);

      if (leadData && centreData?.availability_api_url) {
        const selectedSlot = callAnalysis.selected_slot || extractSlotFromSummary(callSummary);

        const bookingResult = await triggerBooking(env, {
          action: 'book_tour',
          lead_id: leadId,
          centre_id: centreId,
          first_name: leadData.first_name,
          last_name: leadData.last_name,
          phone: leadData.phone,
          email: leadData.email || '',
          calendar_url: centreData.availability_api_url,
          selected_slot: selectedSlot,
          call_summary: callSummary,
          tour_date: tourDate,
          tour_time: tourTime,
          child_name: childName || leadData.first_name,
          child_birth_year: childBirthYear,
        });

        if (bookingResult.success && bookingResult.task_id) {
          await setSkyvernTaskId(env, leadId, bookingResult.task_id, tourDate, tourTime);
          console.log(`Skyvern task ${bookingResult.task_id} tracked for lead ${leadId}`);
        } else if (!bookingResult.success) {
          await updateBookingStatus(env, leadId, {
            booking_status: 'failed',
            booking_failure_reason: bookingResult.error || 'Unknown error',
          });
          console.warn(`Skyvern booking failed for lead ${leadId}: ${bookingResult.error}`);
        }
      } else {
        console.warn('Missing lead or centre data for Skyvern booking:', { leadId, centreId });
        await updateBookingStatus(env, leadId, {
          booking_status: 'failed',
          booking_failure_reason: 'Missing lead or centre data',
        });
      }
    } catch (bookingError) {
      console.error(`Skyvern booking error for lead ${leadId} (booking columns may need migration):`, bookingError);
    }
  }
} else if (isRetryOutcome(outcome)) {
