        "jsCode": "// Calculate next call time for retry\nconst lead = $input.first().json;\nconst windowsUsed = lead.call_windows_tried || [];\nconst currentWindow = lead.current_window || 'morning';\nconst attemptCount = (lead.attempt_count || 0) + 1;\n\nconst allWindows = ['morning', 'afternoon', 'evening'];\n\n// Add current window to used list\nif (!windowsUsed.includes(currentWindow)) {\n  windowsUsed.push(currentWindow);\n}\n\n// Find next unused window, or default to afternoon\nconst nextWindow = allWindows.find(w => !windowsUsed.includes(w)) || 'afternoon';\n\nconst windowStartHours = {\n  morning: 9,    // 9am\n  afternoon: 14, // 2pm  \n  evening: 17    // 5pm\n};\n\n// Schedule for tomorrow (or day after for attempt 3)\nconst now = new Date();\nconst daysToAdd = attemptCount >= 2 ? 2 : 1;  // More gap for later attempts\nconst nextCallDate = new Date(now);\nnextCallDate.setDate(nextCallDate.getDate() + daysToAdd);\nnextCallDate.setHours(windowStartHours[nextWindow], 0, 0, 0);\n\n// Determine new status\nconst newStatus = attemptCount >= 3 ? 'exhausted' : 'pending';\n\nreturn [{\n  json: {\n    lead_id: lead.lead_id,\n    new_status: newStatus,\n    new_attempt_count: attemptCount,\n    call_windows_tried: windowsUsed,\n    next_call_after: attemptCount >= 3 ? null : nextCallDate.toISOString(),\n    last_outcome: lead.outcome,\n    detailed_call_summary: lead.detailed_call_summary\n  }\n}];"
