/**
 * Skyvern callback webhook handler
 * Processes booking completion callbacks from Skyvern
 * Ported from End Of Call - Multicentre n8n workflow
 */

import type { Env, SkyvernCallbackPayload } from '../lib/types';
import { updateBookingStatus, getLeadBySkyvernTaskId } from '../services/supabase';

/**
 * Handles Skyvern webhook callbacks
 * POST /webhook/skyvern
 */
export async function handleSkyvernCallback(request: Request, env: Env): Promise<Response> {
  let payload: SkyvernCallbackPayload;

  try {
    payload = await request.json();
  } catch {
    return errorResponse(400, 'Invalid JSON body');
  }

  const { workflow_run_id, status, failure_reason } = payload;

  if (!workflow_run_id) {
    return errorResponse(400, 'Missing workflow_run_id');
  }

  console.log(`Skyvern callback: task=${workflow_run_id}, status=${status}`);

  try {
    // Look up lead by Skyvern task ID
    const lead = await getLeadBySkyvernTaskId(env, workflow_run_id);

    if (!lead) {
      console.warn(`No lead found for Skyvern task ${workflow_run_id}`);
      return errorResponse(404, 'Lead not found for task ID');
    }

    // Route by status
    switch (status) {
      case 'completed':
        await updateBookingStatus(env, lead.id, {
          booking_status: 'confirmed',
          booking_confirmed_at: new Date().toISOString(),
          booking_failure_reason: null,
        });
        console.log(`Booking confirmed for lead ${lead.id}`);

        // TODO: Send confirmation email if ADMIN_EMAIL configured
        if (env.ADMIN_EMAIL) {
          await sendBookingNotification(env, lead, 'confirmed');
        }
        break;

      case 'failed':
      case 'terminated':
        await updateBookingStatus(env, lead.id, {
          booking_status: 'failed',
          booking_failure_reason: failure_reason || `Skyvern ${status}`,
        });
        console.log(`Booking failed for lead ${lead.id}: ${failure_reason || status}`);

        if (env.ADMIN_EMAIL) {
          await sendBookingNotification(env, lead, 'failed', failure_reason);
        }
        break;

      case 'timed_out':
        await updateBookingStatus(env, lead.id, {
          booking_status: 'failed',
          booking_failure_reason: 'Skyvern timed out after 15 minutes',
        });
        console.log(`Booking timed out for lead ${lead.id}`);

        if (env.ADMIN_EMAIL) {
          await sendBookingNotification(env, lead, 'timeout');
        }
        break;

      case 'running':
        // Task still in progress, ignore
        console.log(`Skyvern task ${workflow_run_id} still running`);
        break;

      default:
        console.warn(`Unknown Skyvern status: ${status}`);
    }

    return new Response(
      JSON.stringify({
        status: 'ok',
        lead_id: lead.id,
        booking_status: status === 'completed' ? 'confirmed' : status,
      }),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Skyvern callback processing error:', error);
    return errorResponse(500, `Processing failed: ${error}`);
  }
}

function errorResponse(status: number, message: string): Response {
  return new Response(
    JSON.stringify({
      status: 'error',
      error: message,
    }),
    {
      status,
      headers: { 'Content-Type': 'application/json' },
    }
  );
}

/**
 * Sends a booking notification email
 * TODO: Implement actual email sending (e.g., via Resend, SendGrid, or Mailgun)
 */
async function sendBookingNotification(
  env: Env,
  lead: { id: string; first_name: string; last_name: string; phone: string; email?: string | null; tour_date?: string | null; tour_time?: string | null; centre_id: string },
  type: 'confirmed' | 'failed' | 'timeout',
  failureReason?: string
): Promise<void> {
  // For now, just log - implement actual email sending when email service is configured
  const subject =
    type === 'confirmed'
      ? `Booking Confirmed: ${lead.first_name} ${lead.last_name}`
      : type === 'timeout'
        ? `Booking Timed Out: ${lead.first_name} ${lead.last_name}`
        : `Booking FAILED: ${lead.first_name} ${lead.last_name}`;

  console.log(`[EMAIL NOTIFICATION] To: ${env.ADMIN_EMAIL}`);
  console.log(`Subject: ${subject}`);
  console.log(`Lead: ${lead.first_name} ${lead.last_name}, Phone: ${lead.phone}`);
  console.log(`Tour: ${lead.tour_date} at ${lead.tour_time}`);
  if (failureReason) {
    console.log(`Failure Reason: ${failureReason}`);
  }

  // TODO: Implement actual email sending
  // Example with Resend:
  // await fetch('https://api.resend.com/emails', {
  //   method: 'POST',
  //   headers: {
  //     'Content-Type': 'application/json',
  //     'Authorization': `Bearer ${env.RESEND_API_KEY}`,
  //   },
  //   body: JSON.stringify({
  //     from: 'noreply@codeninjas.com',
  //     to: env.ADMIN_EMAIL,
  //     subject,
  //     html: `...email content...`,
  //   }),
  // });
}

