// Environment bindings for Cloudflare Worker
export interface Env {
  // Vars (from wrangler.toml)
  RETELL_AGENT_ID: string;
  AVAILABILITY_API_URL: string;
  MAX_LEADS_PER_RUN: string;
  WORKER_URL: string; // e.g., https://lead-reactivation.xprime17.workers.dev

  // Secrets (set via wrangler secret put)
  SUPABASE_URL: string;
  SUPABASE_SERVICE_KEY: string;
  RETELL_API_KEY: string;
  IMPORT_API_KEY: string;

  // Skyvern integration (choose one method)
  SKYVERN_WEBHOOK_URL?: string;  // Simple webhook (fallback)
  SKYVERN_API_URL?: string;      // API base URL (preferred)
  SKYVERN_API_KEY?: string;      // API key for workflow dispatch

  // Notifications
  ADMIN_EMAIL?: string;          // For booking notifications
}

// Database types matching Supabase schema
export interface Centre {
  id: string;
  location_name: string;
  timezone: string;
  timezone_display: string;
  twilio_number: string;
  knowledge_base: string | null;
  max_concurrent_calls: number;
  active_calls: number;
  calling_enabled: boolean;
  availability_api_url: string | null;
}

export interface Lead {
  id: string;
  centre_id: string;
  first_name: string;
  last_name: string;
  phone: string;
  phone_hash: string | null;
  email: string | null;
  program_interest: string | null;
